<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
$env=GreenPortalDatabase::env();$db=GreenPortalDatabase::connect($env,'guniversal_dbp','GUNIVERSAL');
$db->exec("CREATE TABLE IF NOT EXISTS migracao_solicitacoes (
 codsolicitacao BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,codempresa BIGINT UNSIGNED NOT NULL,codusuario BIGINT UNSIGNED NOT NULL,
 bancos_origem JSON NOT NULL,banco_destino VARCHAR(128) NOT NULL,path_ged VARCHAR(1000) NOT NULL,observacoes VARCHAR(2000) NULL,
 status VARCHAR(30) NOT NULL DEFAULT 'EM_CONSTRUCAO',criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,iniciado_em DATETIME NULL,
 finalizado_em DATETIME NULL,erro TEXT NULL,PRIMARY KEY(codsolicitacao),KEY ix_mig_status(status),KEY ix_mig_empresa(codempresa)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci");
$columnCheck=$db->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='migracao_solicitacoes' AND COLUMN_NAME='path_ged_normalizado'");
if(!(int)$columnCheck->fetchColumn())$db->exec("ALTER TABLE migracao_solicitacoes ADD COLUMN path_ged_normalizado VARCHAR(1000) NULL AFTER path_ged");
$migrationColumns=['prompts_replicados'=>'INT NULL','prompts_config_replicados'=>'INT NULL','prompts_hash'=>'CHAR(64) NULL','prompts_detalhes'=>'JSON NULL'];
foreach($migrationColumns as $column=>$definition){$check=$db->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='migracao_solicitacoes' AND COLUMN_NAME=?");$check->execute([$column]);if(!(int)$check->fetchColumn())$db->exec('ALTER TABLE migracao_solicitacoes ADD COLUMN `'.$column.'` '.$definition);}
$db->exec("CREATE TABLE IF NOT EXISTS migracao_etapas (
 codetapa BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,codsolicitacao BIGINT UNSIGNED NOT NULL,ordem INT NOT NULL,codigo VARCHAR(80) NOT NULL,nome VARCHAR(180) NOT NULL,
 status VARCHAR(30) NOT NULL DEFAULT 'PENDENTE',inicio_em DATETIME NULL,fim_em DATETIME NULL,quantidade BIGINT NULL,detalhes JSON NULL,erro TEXT NULL,
 PRIMARY KEY(codetapa),UNIQUE KEY uk_mig_etapa(codsolicitacao,codigo),KEY ix_mig_etapa_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci");
$db->exec("CREATE TABLE IF NOT EXISTS migracao_logs (
 codlog BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,codsolicitacao BIGINT UNSIGNED NOT NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,nivel VARCHAR(15) NOT NULL DEFAULT 'INFO',etapa VARCHAR(80) NULL,mensagem TEXT NOT NULL,detalhes JSON NULL,PRIMARY KEY(codlog),KEY ix_mig_log(codsolicitacao,criado_em)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci");
$db->exec("CREATE TABLE IF NOT EXISTS migracao_prompts_fila (
 codfila BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,codsolicitacao BIGINT UNSIGNED NULL,codusuario BIGINT UNSIGNED NOT NULL,banco_destino VARCHAR(128) NOT NULL,
 status VARCHAR(30) NOT NULL DEFAULT 'SOLICITADA',criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,iniciado_em DATETIME NULL,finalizado_em DATETIME NULL,erro TEXT NULL,detalhes JSON NULL,
 PRIMARY KEY(codfila),KEY ix_prompt_fila_status(status,criado_em),KEY ix_prompt_fila_destino(banco_destino)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci");
$db->exec("CREATE TABLE IF NOT EXISTS migracao_menus_nao_mapeados (
 codregistro BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,banco_destino VARCHAR(128) NOT NULL,codgrupo_legado BIGINT NULL,codmenu_legado BIGINT NULL,codigo_legado VARCHAR(500) NULL,label_legado VARCHAR(500) NULL,codmenu_destino BIGINT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDENTE',validado_por BIGINT NULL,validado_em DATETIME NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(codregistro),KEY ix_menu_pendente(banco_destino,status),KEY ix_menu_destino(codmenu_destino)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci");
$menuColumns=['codmenu_destino'=>'BIGINT NULL','validado_por'=>'BIGINT NULL','validado_em'=>'DATETIME NULL'];
foreach($menuColumns as $column=>$definition){$check=$db->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='migracao_menus_nao_mapeados' AND COLUMN_NAME=?");$check->execute([$column]);if(!(int)$check->fetchColumn())$db->exec('ALTER TABLE migracao_menus_nao_mapeados ADD COLUMN `'.$column.'` '.$definition);}
$db->exec("UPDATE migracao_menus_nao_mapeados SET codigo_legado=CONCAT('LEGADO_MENU_',codmenu_legado),label_legado=CONCAT('Menu legado #',codmenu_legado) WHERE (codigo_legado IS NULL OR codigo_legado='') AND (label_legado IS NULL OR label_legado='') AND codmenu_legado IS NOT NULL");
$db->exec("CREATE OR REPLACE VIEW vw_empresa_migracao_grid AS SELECT e.codempresa,e.codigo,e.nome,e.status,e.banco_dados,e.ged,e.cnpj,e.cidade,e.bloqueada,c.codconfig,c.codigo_legado,c.banco_legado,c.banco_legado_seguranca,c.banco_novo,c.banco_novo_seguranca,c.status_migracao,c.sincronismo_ativo,c.ultima_validacao_em,c.ultima_migracao_em,c.ultimo_sincronismo_em,c.origem_cadastro,c.observacoes,c.atualizado_em FROM empresa e LEFT JOIN empresa_migracao_config c ON c.codempresa=e.codempresa");
$db->exec("CREATE OR REPLACE VIEW vw_empresas_login_migradas AS SELECT DISTINCT e.codempresa,e.codigo,e.nome,e.status,e.banco_dados,e.ged FROM empresa e INNER JOIN empresa_migracao_config c ON c.codempresa=e.codempresa INNER JOIN information_schema.SCHEMATA s ON s.SCHEMA_NAME=c.banco_novo WHERE e.status='ATIVA' AND COALESCE(e.bloqueada,'N')<>'S'");
$db->exec("CREATE OR REPLACE VIEW vw_migracao_solicitacoes AS SELECT s.*,e.codigo,e.nome AS empresa_nome,(SELECT COUNT(*) FROM migracao_etapas x WHERE x.codsolicitacao=s.codsolicitacao) etapas_total,(SELECT COUNT(*) FROM migracao_etapas x WHERE x.codsolicitacao=s.codsolicitacao AND x.status='CONCLUIDA') etapas_concluidas FROM migracao_solicitacoes s JOIN empresa e ON e.codempresa=s.codempresa");
$procedures=[];
$procedures['sp_migracao_solicitacao_criar']="CREATE PROCEDURE sp_migracao_solicitacao_criar(IN p_empresa BIGINT,IN p_usuario BIGINT,IN p_origens JSON,IN p_destino VARCHAR(128),IN p_ged VARCHAR(1000),IN p_obs VARCHAR(2000)) BEGIN DECLARE v_id BIGINT; IF JSON_TYPE(p_origens) <> 'ARRAY' OR JSON_LENGTH(p_origens)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Informe ao menos um banco de origem'; END IF; IF p_destino NOT REGEXP '^g[a-z0-9]+_dbp$' OR p_ged='' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Destino ou caminho GED invalido'; END IF; INSERT INTO migracao_solicitacoes(codempresa,codusuario,bancos_origem,banco_destino,path_ged,observacoes) VALUES(p_empresa,p_usuario,p_origens,p_destino,p_ged,p_obs); SET v_id=LAST_INSERT_ID(); INSERT INTO migracao_etapas(codsolicitacao,ordem,codigo,nome) VALUES (v_id,1,'VALIDAR_CONFIGURACAO','Validar configuracao'),(v_id,2,'PROVISIONAR_DESTINO','Provisionar banco destino'),(v_id,3,'BACKUP_DESTINO','Backup do banco destino'),(v_id,4,'MIGRAR_SEGURANCA','Migrar seguranca'),(v_id,5,'REPLICAR_PROMPTS_IA','Replicar prompts de IA'),(v_id,6,'MIGRAR_MODULO_LEGAL','Migrar Modulo Legal'),(v_id,7,'AUDITAR_ORFAOS','Auditar registros orfaos'),(v_id,8,'MAPEAR_GED','Mapear GED'),(v_id,9,'VALIDAR_RESULTADO','Validar resultado'); SELECT v_id codsolicitacao; END";
$procedures['sp_migracao_solicitacao_iniciar']="CREATE PROCEDURE sp_migracao_solicitacao_iniciar(IN p_id BIGINT,IN p_usuario BIGINT) BEGIN UPDATE migracao_solicitacoes SET status='EM_EXECUCAO',iniciado_em=COALESCE(iniciado_em,CURRENT_TIMESTAMP),erro=NULL WHERE codsolicitacao=p_id AND status='EM_CONSTRUCAO'; IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Solicitacao nao esta em construcao'; END IF; INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem) VALUES(p_id,'INFO','SISTEMA','Migracao iniciada pelo usuario'); SELECT * FROM vw_migracao_solicitacoes WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_solicitacao_reprocessar']="CREATE PROCEDURE sp_migracao_solicitacao_reprocessar(IN p_id BIGINT,IN p_usuario BIGINT) BEGIN UPDATE migracao_solicitacoes SET status='EM_EXECUCAO',iniciado_em=CURRENT_TIMESTAMP,finalizado_em=NULL,erro=NULL WHERE codsolicitacao=p_id AND status='ERRO'; IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Somente solicitacoes em erro podem ser reprocessadas'; END IF; UPDATE migracao_etapas SET status='PENDENTE',inicio_em=NULL,fim_em=NULL,quantidade=NULL,detalhes=NULL,erro=NULL WHERE codsolicitacao=p_id; INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem) VALUES(p_id,'INFO','SISTEMA','Migracao reprocessada pelo usuario'); SELECT * FROM vw_migracao_solicitacoes WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_solicitacao_corrigir_origens']="CREATE PROCEDURE sp_migracao_solicitacao_corrigir_origens(IN p_id BIGINT,IN p_usuario BIGINT,IN p_origens JSON) BEGIN IF JSON_TYPE(p_origens)<>'ARRAY' OR JSON_LENGTH(p_origens)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Origens invalidas'; END IF; UPDATE migracao_solicitacoes SET bancos_origem=p_origens,status='EM_EXECUCAO',iniciado_em=CURRENT_TIMESTAMP,finalizado_em=NULL,erro=NULL WHERE codsolicitacao=p_id AND status='ERRO'; IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Somente solicitacoes em erro podem ter as origens corrigidas'; END IF; UPDATE migracao_etapas SET status='PENDENTE',inicio_em=NULL,fim_em=NULL,quantidade=NULL,detalhes=NULL,erro=NULL WHERE codsolicitacao=p_id; SELECT * FROM vw_migracao_solicitacoes WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_solicitacao_normalizar_ged']="CREATE PROCEDURE sp_migracao_solicitacao_normalizar_ged(IN p_id BIGINT,IN p_ged VARCHAR(1000)) BEGIN UPDATE migracao_solicitacoes SET path_ged_normalizado=p_ged WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_prompts_atualizar']="CREATE PROCEDURE sp_migracao_prompts_atualizar(IN p_id BIGINT,IN p_prompts INT,IN p_config INT,IN p_hash CHAR(64),IN p_detalhes JSON) BEGIN UPDATE migracao_solicitacoes SET prompts_replicados=p_prompts,prompts_config_replicados=p_config,prompts_hash=p_hash,prompts_detalhes=p_detalhes WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_log_registrar']="CREATE PROCEDURE sp_migracao_log_registrar(IN p_id BIGINT,IN p_nivel VARCHAR(15),IN p_etapa VARCHAR(80),IN p_mensagem TEXT,IN p_detalhes JSON) BEGIN INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem,detalhes) VALUES(p_id,p_nivel,p_etapa,p_mensagem,p_detalhes); END";
$procedures['sp_migracao_prompts_solicitar']="CREATE PROCEDURE sp_migracao_prompts_solicitar(IN p_solicitacao BIGINT,IN p_usuario BIGINT,IN p_destino VARCHAR(128)) BEGIN INSERT INTO migracao_prompts_fila(codsolicitacao,codusuario,banco_destino) VALUES(NULLIF(p_solicitacao,0),p_usuario,p_destino); SELECT LAST_INSERT_ID() codfila; END";
$procedures['sp_migracao_prompts_reivindicar']="CREATE PROCEDURE sp_migracao_prompts_reivindicar() BEGIN DECLARE v_id BIGINT DEFAULT 0; START TRANSACTION; SELECT codfila INTO v_id FROM migracao_prompts_fila WHERE status='SOLICITADA' ORDER BY criado_em,codfila LIMIT 1 FOR UPDATE; IF v_id>0 THEN UPDATE migracao_prompts_fila SET status='EM_EXECUCAO',iniciado_em=CURRENT_TIMESTAMP WHERE codfila=v_id; SELECT * FROM migracao_prompts_fila WHERE codfila=v_id; END IF; COMMIT; END";
$procedures['sp_migracao_prompts_finalizar']="CREATE PROCEDURE sp_migracao_prompts_finalizar(IN p_id BIGINT,IN p_status VARCHAR(30),IN p_erro TEXT,IN p_detalhes JSON) BEGIN UPDATE migracao_prompts_fila SET status=p_status,finalizado_em=CURRENT_TIMESTAMP,erro=p_erro,detalhes=p_detalhes WHERE codfila=p_id; IF EXISTS(SELECT 1 FROM migracao_prompts_fila WHERE codfila=p_id AND codsolicitacao IS NOT NULL) THEN INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem,detalhes) SELECT codsolicitacao,IF(p_status='CONCLUIDA','INFO','ERRO'),'REPLICAR_PROMPTS_IA',IF(p_status='CONCLUIDA','Replicacao de prompts concluida pelo worker.',COALESCE(p_erro,'Replicacao de prompts falhou.')),p_detalhes FROM migracao_prompts_fila WHERE codfila=p_id; END IF; END";
$procedures['sp_migracao_prompts_detalhe_obter']="CREATE PROCEDURE sp_migracao_prompts_detalhe_obter(IN p_id BIGINT) BEGIN SELECT codsolicitacao,prompts_replicados,prompts_config_replicados,prompts_hash,prompts_detalhes FROM migracao_solicitacoes WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_menu_nao_mapeado_registrar']="CREATE PROCEDURE sp_migracao_menu_nao_mapeado_registrar(IN p_destino VARCHAR(128),IN p_grupo BIGINT,IN p_menu BIGINT,IN p_codigo VARCHAR(500),IN p_label VARCHAR(500)) BEGIN INSERT INTO migracao_menus_nao_mapeados(banco_destino,codgrupo_legado,codmenu_legado,codigo_legado,label_legado) SELECT p_destino,p_grupo,p_menu,p_codigo,p_label FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM migracao_menus_nao_mapeados WHERE banco_destino=p_destino AND COALESCE(codgrupo_legado,0)=COALESCE(p_grupo,0) AND COALESCE(codmenu_legado,0)=COALESCE(p_menu,0) AND COALESCE(codigo_legado,'')=COALESCE(p_codigo,'') AND COALESCE(label_legado,'')=COALESCE(p_label,'')); END";
$procedures['sp_migracao_menus_nao_mapeados_listar']="CREATE PROCEDURE sp_migracao_menus_nao_mapeados_listar(IN p_destino VARCHAR(128),IN p_status VARCHAR(30),IN p_busca VARCHAR(255),IN p_limite INT,IN p_offset INT) BEGIN SELECT n.*,m.codigo codigo_destino,m.label label_destino FROM migracao_menus_nao_mapeados n LEFT JOIN menus m ON m.codmenu=n.codmenu_destino WHERE (p_destino='' OR n.banco_destino=p_destino) AND (p_status='' OR n.status=p_status) AND (p_busca='' OR CONVERT(n.codigo_legado USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci OR CONVERT(n.label_legado USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci OR CONVERT(n.codmenu_legado USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci OR CONVERT(n.banco_destino USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci) ORDER BY n.banco_destino,n.status,n.label_legado,n.codregistro LIMIT p_offset,p_limite; END";
$procedures['sp_migracao_menus_nao_mapeados_count']="CREATE PROCEDURE sp_migracao_menus_nao_mapeados_count(IN p_destino VARCHAR(128),IN p_status VARCHAR(30),IN p_busca VARCHAR(255)) BEGIN SELECT COUNT(*) total FROM migracao_menus_nao_mapeados n WHERE (p_destino='' OR n.banco_destino=p_destino) AND (p_status='' OR n.status=p_status) AND (p_busca='' OR CONVERT(n.codigo_legado USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci OR CONVERT(n.label_legado USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci OR CONVERT(n.codmenu_legado USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci OR CONVERT(n.banco_destino USING utf8mb4) COLLATE utf8mb4_0900_ai_ci LIKE CONVERT(CONCAT('%',p_busca,'%') USING utf8mb4) COLLATE utf8mb4_0900_ai_ci); END";
$procedures['sp_migracao_menu_nao_mapeado_associar']="CREATE PROCEDURE sp_migracao_menu_nao_mapeado_associar(IN p_id BIGINT,IN p_destino VARCHAR(128),IN p_menu BIGINT,IN p_usuario BIGINT,IN p_status VARCHAR(30)) BEGIN IF p_status NOT IN ('PENDENTE','VALIDADO','IGNORADO') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Status de validacao invalido'; END IF; IF NOT EXISTS(SELECT 1 FROM migracao_menus_nao_mapeados WHERE codregistro=p_id AND banco_destino=p_destino) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Registro de menu nao encontrado'; END IF; IF p_status='VALIDADO' AND (p_menu IS NULL OR p_menu=0 OR NOT EXISTS(SELECT 1 FROM menus WHERE codmenu=p_menu AND ativo=1)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Informe um menu universal ativo para validar'; END IF; UPDATE migracao_menus_nao_mapeados SET codmenu_destino=NULLIF(p_menu,0),status=p_status,validado_por=p_usuario,validado_em=CURRENT_TIMESTAMP WHERE codregistro=p_id AND banco_destino=p_destino; SELECT * FROM migracao_menus_nao_mapeados WHERE codregistro=p_id; END";
$procedures['sp_migracao_solicitacao_atualizar']="CREATE PROCEDURE sp_migracao_solicitacao_atualizar(IN p_id BIGINT,IN p_usuario BIGINT,IN p_origens JSON,IN p_destino VARCHAR(128),IN p_ged VARCHAR(1000),IN p_obs VARCHAR(2000)) BEGIN IF JSON_TYPE(p_origens) <> 'ARRAY' OR JSON_LENGTH(p_origens)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Informe ao menos um banco de origem'; END IF; IF p_destino NOT REGEXP '^g[a-z0-9]+_dbp$' OR p_ged='' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Destino ou caminho GED invalido'; END IF; UPDATE migracao_solicitacoes SET bancos_origem=p_origens,banco_destino=p_destino,path_ged=p_ged,observacoes=p_obs,erro=NULL WHERE codsolicitacao=p_id AND status='EM_CONSTRUCAO'; IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Somente solicitacoes em construcao podem ser alteradas'; END IF; INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem) VALUES(p_id,'INFO','SISTEMA','Parametros atualizados'); SELECT * FROM vw_migracao_solicitacoes WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_solicitacao_excluir']="CREATE PROCEDURE sp_migracao_solicitacao_excluir(IN p_id BIGINT,IN p_usuario BIGINT) BEGIN IF NOT EXISTS(SELECT 1 FROM migracao_solicitacoes WHERE codsolicitacao=p_id AND status='EM_CONSTRUCAO') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Somente solicitacoes em construcao podem ser excluidas'; END IF; DELETE FROM migracao_logs WHERE codsolicitacao=p_id; DELETE FROM migracao_etapas WHERE codsolicitacao=p_id; DELETE FROM migracao_solicitacoes WHERE codsolicitacao=p_id; SELECT p_id codsolicitacao; END";
$procedures['sp_migracao_solicitacoes_listar']="CREATE PROCEDURE sp_migracao_solicitacoes_listar(IN p_status VARCHAR(30),IN p_busca VARCHAR(255),IN p_limite INT,IN p_offset INT) BEGIN SELECT * FROM vw_migracao_solicitacoes WHERE (p_status='' OR status=p_status) AND (p_busca='' OR empresa_nome LIKE CONCAT('%',p_busca,'%') OR codigo LIKE CONCAT('%',p_busca,'%') OR banco_destino LIKE CONCAT('%',p_busca,'%')) ORDER BY criado_em DESC LIMIT p_offset,p_limite; END";
$procedures['sp_migracao_solicitacoes_count']="CREATE PROCEDURE sp_migracao_solicitacoes_count(IN p_status VARCHAR(30),IN p_busca VARCHAR(255)) BEGIN SELECT COUNT(*) total FROM vw_migracao_solicitacoes WHERE (p_status='' OR status=p_status) AND (p_busca='' OR empresa_nome LIKE CONCAT('%',p_busca,'%') OR codigo LIKE CONCAT('%',p_busca,'%') OR banco_destino LIKE CONCAT('%',p_busca,'%')); END";
$procedures['sp_migracao_solicitacao_obter']="CREATE PROCEDURE sp_migracao_solicitacao_obter(IN p_id BIGINT) BEGIN SELECT * FROM vw_migracao_solicitacoes WHERE codsolicitacao=p_id; SELECT * FROM migracao_etapas WHERE codsolicitacao=p_id ORDER BY ordem; END";
$procedures['sp_migracao_worker_proxima']="CREATE PROCEDURE sp_migracao_worker_proxima() BEGIN SELECT * FROM migracao_solicitacoes WHERE status='EM_EXECUCAO' ORDER BY iniciado_em,codsolicitacao LIMIT 1; END";
$procedures['sp_migracao_worker_reivindicar']="CREATE PROCEDURE sp_migracao_worker_reivindicar() BEGIN DECLARE v_id BIGINT DEFAULT 0; START TRANSACTION; SELECT codsolicitacao INTO v_id FROM migracao_solicitacoes WHERE status='EM_EXECUCAO' ORDER BY iniciado_em,codsolicitacao LIMIT 1 FOR UPDATE; IF v_id>0 THEN UPDATE migracao_solicitacoes SET status='WORKER_EM_EXECUCAO' WHERE codsolicitacao=v_id; SELECT * FROM migracao_solicitacoes WHERE codsolicitacao=v_id; END IF; COMMIT; END";
$procedures['sp_migracao_etapa_iniciar']="CREATE PROCEDURE sp_migracao_etapa_iniciar(IN p_id BIGINT,IN p_codigo VARCHAR(80)) BEGIN UPDATE migracao_etapas SET status='EM_EXECUCAO',inicio_em=COALESCE(inicio_em,CURRENT_TIMESTAMP),erro=NULL WHERE codsolicitacao=p_id AND codigo=p_codigo AND status='PENDENTE'; INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem) VALUES(p_id,'INFO',p_codigo,'Etapa iniciada'); END";
$procedures['sp_migracao_etapa_concluir']="CREATE PROCEDURE sp_migracao_etapa_concluir(IN p_id BIGINT,IN p_codigo VARCHAR(80),IN p_qtd BIGINT,IN p_detalhes JSON) BEGIN UPDATE migracao_etapas SET status='CONCLUIDA',fim_em=CURRENT_TIMESTAMP,quantidade=p_qtd,detalhes=p_detalhes WHERE codsolicitacao=p_id AND codigo=p_codigo; INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem,detalhes) VALUES(p_id,'INFO',p_codigo,'Etapa concluida',p_detalhes); END";
$procedures['sp_migracao_etapa_erro']="CREATE PROCEDURE sp_migracao_etapa_erro(IN p_id BIGINT,IN p_codigo VARCHAR(80),IN p_erro TEXT,IN p_detalhes JSON) BEGIN UPDATE migracao_etapas SET status='ERRO',fim_em=CURRENT_TIMESTAMP,erro=p_erro,detalhes=p_detalhes WHERE codsolicitacao=p_id AND codigo=p_codigo; UPDATE migracao_solicitacoes SET status='ERRO',finalizado_em=CURRENT_TIMESTAMP,erro=p_erro WHERE codsolicitacao=p_id; INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem,detalhes) VALUES(p_id,'ERRO',p_codigo,p_erro,p_detalhes); END";
$procedures['sp_migracao_finalizar']="CREATE PROCEDURE sp_migracao_finalizar(IN p_id BIGINT) BEGIN IF EXISTS(SELECT 1 FROM migracao_etapas WHERE codsolicitacao=p_id AND status='ERRO') THEN UPDATE migracao_solicitacoes SET status='ERRO',finalizado_em=CURRENT_TIMESTAMP WHERE codsolicitacao=p_id; ELSEIF NOT EXISTS(SELECT 1 FROM migracao_etapas WHERE codsolicitacao=p_id AND status<>'CONCLUIDA') THEN UPDATE migracao_solicitacoes SET status='FINALIZADO_COM_SUCESSO',finalizado_em=CURRENT_TIMESTAMP,erro=NULL WHERE codsolicitacao=p_id; INSERT INTO migracao_logs(codsolicitacao,nivel,etapa,mensagem) VALUES(p_id,'INFO','SISTEMA','Migracao finalizada com sucesso'); END IF; SELECT status FROM migracao_solicitacoes WHERE codsolicitacao=p_id; END";
$procedures['sp_migracao_logs']="CREATE PROCEDURE sp_migracao_logs(IN p_id BIGINT) BEGIN SELECT codlog,criado_em,nivel,etapa,mensagem,detalhes FROM migracao_logs WHERE codsolicitacao=p_id ORDER BY codlog; END";
$procedures['sp_migracao_configurar_bancos']="CREATE PROCEDURE sp_migracao_configurar_bancos(IN p_empresa BIGINT,IN p_legado VARCHAR(128),IN p_legado_seg VARCHAR(128),IN p_novo VARCHAR(128),IN p_ged VARCHAR(1000)) BEGIN IF p_novo NOT REGEXP '^g[a-z0-9]+_dbp$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Banco novo invalido'; END IF; UPDATE empresa SET banco_dados=p_novo,ged=p_ged WHERE codempresa=p_empresa; UPDATE empresa_migracao_config SET banco_legado=p_legado,banco_legado_seguranca=p_legado_seg,banco_novo=p_novo,banco_novo_seguranca=p_novo,observacoes=CONCAT(COALESCE(observacoes,''),' Configuracao atualizada pela solicitacao 275.') WHERE codempresa=p_empresa; SELECT * FROM vw_empresa_migracao_grid WHERE codempresa=p_empresa; END";
foreach($procedures as $name=>$sql){$db->exec('DROP PROCEDURE IF EXISTS '.$name);$db->exec($sql);}
echo json_encode(['ok'=>true,'procedures'=>array_keys($procedures),'view'=>'vw_migracao_solicitacoes'],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;
